  /**
   * Tests for: docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
   * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md
   * @req REQ-FORMAT-SPECIFICATION - Verify valid-annotation-format rule enforces annotation format syntax
   */

  describe("Valid Annotation Format Rule (Story 005.0-DEV-ANNOTATION-VALIDATION)", () => {
    ruleTester.run("valid-annotation-format", rule, {
      valid: [
        { name: "[REQ-PATH-FORMAT] valid story annotation format (single-line)", code: `// @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md` },
        { name: "[REQ-REQ-FORMAT] valid req annotation format (single-line)", code: `// @req REQ-EXAMPLE` },
        { name: "[REQ-FORMAT-SPECIFICATION] valid block annotations (single-line values)", code: `/**\n * @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md\n * @req REQ-VALID-EXAMPLE\n */` },
        { name: "[REQ-MULTILINE-SUPPORT] valid multi-line @story annotation value in block comment", code: `/**\n * @story docs/stories/005.0-\n * DEV-ANNOTATION-VALIDATION.story.md\n */` },
        { name: "[REQ-MULTILINE-SUPPORT] valid multi-line @req annotation value in block comment", code: `/**\n * @req REQ-\n * EXAMPLE\n */` },
        { name: "[REQ-FLEXIBLE-PARSING] valid JSDoc-style comment with leading stars and spacing", code: `/**\n *   @story   docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md\n *   @req   REQ-FLEXIBLE-PARSING\n */` },
      ],
      invalid: [
        { name: "[REQ-PATH-FORMAT] missing story path (single line)", code: `// @story`, errors: [{ messageId: "invalidStoryFormat", data: { details: 'Missing story path for @story annotation. Expected a path like "docs/stories/005.0-DEV-EXAMPLE.story.md".' } }] },
        { name: "[REQ-PATH-FORMAT] invalid story file extension", code: `// @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story`, output: `// @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md`, errors: [{ messageId: "invalidStoryFormat", data: { details: 'Invalid story path "docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story" for @story annotation. Expected a path like "docs/stories/005.0-DEV-EXAMPLE.story.md".' } }] },
        { name: "[REQ-PATH-FORMAT] missing extension in story path", code: `// @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION`, output: `// @story docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md`, errors: [{ messageId: "invalidStoryFormat", data: { details: 'Invalid story path "docs/stories/005.0-DEV-ANNOTATION-VALIDATION" for @story annotation. Expected a path like "docs/stories/005.0-DEV-EXAMPLE.story.md".' } }] },
        { name: "[REQ-PATH-FORMAT] story path must not use path traversal", code: `// @story ../docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md`, errors: [{ messageId: "invalidStoryFormat", data: { details: 'Invalid story path "../docs/stories/005.0-DEV-ANNOTATION-VALIDATION.story.md" for @story annotation. Expected a path like "docs/stories/005.0-DEV-EXAMPLE.story.md".' } }] },
        { name: "[REQ-REQ-FORMAT] missing req id (single line)", code: `// @req`, errors: [{ messageId: "invalidReqFormat", data: { details: 'Missing requirement ID for @req annotation. Expected an identifier like "REQ-EXAMPLE".' } }] },
        { name: "[REQ-REQ-FORMAT] invalid req id format (single line)", code: `// @req invalid-format`, errors: [{ messageId: "invalidReqFormat", data: { details: 'Invalid requirement ID "invalid-format" for @req annotation. Expected an identifier like "REQ-EXAMPLE" (uppercase letters, numbers, and dashes only).'} }] },
        // additional invalid multi-line story/req examples also mirror the story spec
